<?php namespace App\Models; use App\Enums\OrderStatus; use Illuminate\Database\Eloquent\Model; class Order extends Model { protected $fillable=['number','customer_id','vendor_id','shipping_address','billing_address','status','subtotal','discount_total','tax_total','shipping_total','grand_total','placed_at']; protected function casts():array{return ['shipping_address'=>'array','billing_address'=>'array','status'=>OrderStatus::class,'subtotal'=>'decimal:2','discount_total'=>'decimal:2','tax_total'=>'decimal:2','shipping_total'=>'decimal:2','grand_total'=>'decimal:2','placed_at'=>'datetime'];} public function customer(){return $this->belongsTo(User::class,'customer_id');} public function vendor(){return $this->belongsTo(Vendor::class);} public function items(){return $this->hasMany(OrderItem::class);} public function payment(){return $this->hasOne(Payment::class);} }
